import{_ as d,o,c as r,a2 as a}from"./chunks/framework.BjkiRu3Q.js";const p=JSON.parse('{"title":"把需求写给 AI：一份秒杀需求的返工记录","description":"","frontmatter":{"title":"把需求写给 AI：一份秒杀需求的返工记录"},"headers":[],"relativePath":"md/ai-code/requirement.md","filePath":"md/ai-code/requirement.md","lastUpdated":1795434315000}'),e={name:"md/ai-code/requirement.md"};function n(i,t,u,s,l,h){return o(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="把需求写给-ai-一份秒杀需求的返工记录" tabindex="-1">把需求写给 AI：一份秒杀需求的返工记录 <a class="header-anchor" href="#把需求写给-ai-一份秒杀需求的返工记录" aria-label="Permalink to &quot;把需求写给 AI：一份秒杀需求的返工记录&quot;">​</a></h1><p>我用 AI 写了一个秒杀系统。代码几乎是它独立完成的，我做的事是写需求、压测、找问题、定取舍。</p><p>结果第一个交付版本里，<strong>四个缺陷全部不是&quot;代码写错了&quot;，而是&quot;我没写清楚&quot;</strong>。这篇记录那四个漏项，以及补完之后需求文档该长什么样。</p><h2 id="需求文档的读者变了" tabindex="-1">需求文档的读者变了 <a class="header-anchor" href="#需求文档的读者变了" aria-label="Permalink to &quot;需求文档的读者变了&quot;">​</a></h2><p>写给同事的需求，人会自动补常识：他不会把库存扣成负数，不会在缓存挂掉时抛 500，知道&quot;限流&quot;该按什么维度限。</p><p>AI 不补。它按字面执行，<strong>你没写的地方，它就给你一个&quot;看起来能跑&quot;的默认</strong>。这个默认往往是合理的通用实现，只是不适合你的业务。</p><p>所以需求的写法要换：从&quot;描述功能&quot;改成&quot;写清契约和验收标准&quot;。判断标准很简单 —— 拿这份需求，一个没参与过讨论的工程师能不能独立交付？如果他必须回来问一句，那句话就是 AI 会替你擅自决定的地方。</p><h2 id="这次漏了四个" tabindex="-1">这次漏了四个 <a class="header-anchor" href="#这次漏了四个" aria-label="Permalink to &quot;这次漏了四个&quot;">​</a></h2><table tabindex="0"><thead><tr><th>漏项</th><th>AI 的默认</th><th>后果</th></tr></thead><tbody><tr><td>并发量级没给数字</td><td>做了单活动库存校验，没做全局 QPS 限流</td><td>活动再多一点，数据库先倒</td></tr><tr><td>限流没定维度</td><td>按 IP，20 次/秒</td><td>100 人共用一个出口 IP，只成交 20 单，少卖 98%</td></tr><tr><td>依赖不可用的语义没写</td><td>Redis 异常走通用异常处理</td><td>返回 <strong>500</strong>，调用方无法区分&quot;系统坏了&quot;和&quot;你买晚了&quot;</td></tr><tr><td>缓存丢失后的行为没写</td><td>视为&quot;活动不存在&quot;，返回 503</td><td>重启后<strong>永久 503</strong>，必须人工恢复</td></tr></tbody></table><p>第一条和第二条是同一个问题的两半：我只写了&quot;要限流&quot;，没写&quot;按什么限、为什么限&quot;。AI 选 IP 是最省事的选择，而秒杀的真实流量里，NAT 出口和脚本共用 IP 的情况极多。</p><p>第三条尤其典型。500 和 503 在代码里差一行，在语义上差一个世界：500 是&quot;我的 bug&quot;，503 是&quot;我暂时不行，你可以重试&quot;。前者会让上游报警、让人查日志；后者是正常的容量管理信号。</p><h2 id="于是需求该写哪几段" tabindex="-1">于是需求该写哪几段 <a class="header-anchor" href="#于是需求该写哪几段" aria-label="Permalink to &quot;于是需求该写哪几段&quot;">​</a></h2><p>补完之后我的需求文档是六个部分，功能描述只占很小一块：</p><ol><li><strong>业务规则</strong> —— 谁能买、买几次、活动怎么开始和结束</li><li><strong>一致性口径</strong> —— 允许超卖还是零超卖。这个是取舍不是需求，必须显式写下来，否则 AI 会按&quot;看起来对&quot;的方式实现</li><li><strong>容量与延迟</strong> —— 目标 QPS、库存量级、P95 上限。没有数字就没有验收标准</li><li><strong>失败语义矩阵</strong> —— 每一种失败必须写明：状态码、错误码、用户可见文案、是否可重试</li><li><strong>依赖降级</strong> —— 数据库、缓存、下游服务各自不可用时，系统该退化成什么</li><li><strong>验收方式</strong> —— 用什么工具测、看哪些指标、三方数据怎么对账</li></ol><p>第四条是最值钱的一段，也是最容易被略过的。写成矩阵：</p><table tabindex="0"><thead><tr><th>场景</th><th>HTTP</th><th>错误码</th><th>可重试</th></tr></thead><tbody><tr><td>库存不足</td><td>409</td><td>SOLD_OUT</td><td>否</td></tr><tr><td>已参与过</td><td>409</td><td>ALREADY_PARTICIPATED</td><td>否</td></tr><tr><td>触发限流</td><td>429</td><td>RATE_LIMITED</td><td>是，退避后</td></tr><tr><td>缓存不可用</td><td>503</td><td>SYSTEM_NOT_READY</td><td>是</td></tr><tr><td>未知异常</td><td>500</td><td>INTERNAL_ERROR</td><td>否</td></tr></tbody></table><p>这张表写出来，AI 的实现就不会跑偏；写不出来，说明自己还没想清楚。</p><h2 id="第四条漏了会怎样" tabindex="-1">第四条漏了会怎样 <a class="header-anchor" href="#第四条漏了会怎样" aria-label="Permalink to &quot;第四条漏了会怎样&quot;">​</a></h2><p>上面四个缺陷，我修的是后两个（500 → 503，缓存自愈重建）。前两个没修：全局限流是容量问题，IP 阈值是业务策略问题 —— <strong>策略不该由代码猜，也不该由 AI 猜</strong>。</p><p>这也是这次最大的收获：AI 编程把&quot;实现&quot;的成本压得很低，成本就全部转移到了&quot;把话说清楚&quot;上。需求文档写细，不是流程官僚，是因为现在唯一的瓶颈就在这里了。</p><p>写需求的成本前移了，但比返工便宜得多 —— 尤其当你没法肉眼判断它写对没写对的时候。</p><p>下一篇是验收侧的记录：<a href="./acceptance.html">6 轮压测和 2 个 P0</a>。</p>',22)])])}const c=d(e,[["render",n]]);export{p as __pageData,c as default};
